def f(grid):
    h=len(grid); out=[r[:] for r in grid]
    for j,v in enumerate(grid[-1]):
        if v==5:
            col=[grid[i][j] for i in range(h)]
            nz=[i for i in range(h) if col[i]]
            if not nz: continue
            top=nz[0]
            for i in range(h):
                if col[i]: continue
                below=[k for k in nz if k>i]
                out[i][j]=col[top] if not below else col[below[0]]
    return out
